# Tool Chain Composer demo: schema-checked DAG assembly + dry run.
TOOLS={"fetch":{"out":["text"],"fn":lambda: "raw TEXT "},
       "clean":{"in":["text"],"out":["text"],"fn":lambda t:t.strip().lower()},
       "count":{"in":["text"],"out":["report"],"fn":lambda t:{"words":len(t.split())}}}
def compose(names):
    for a,b in zip(names,names[1:]):
        if not set(TOOLS[a]["out"])&set(TOOLS[b].get("in",[])):
            raise ValueError("cannot connect %s -> %s"%(a,b))
    return names
chain=compose(["fetch","clean","count"])
data=None
for name in chain:
    data=TOOLS[name]["fn"]() if data is None else TOOLS[name]["fn"](data)
print("chain:",chain,"->",data)

